"""Built-in shortcut presets for Keymapper.

Entries carry the full modern schema (repeat, any, extra_keybinds;
per-op use_multi_contexts/expand_contexts). Operators with an
unambiguous home use auto-context (empty context); generic wm.*
dispatchers keep an explicit context.

Each preset is stamped with source_preset_id / source_preset_category
when applied, so it can be identified and cleaned up later.
"""

PRESET_CATEGORIES = [
    {'id': 'default', 'label': '', 'mutually_exclusive': False},
]


def addon_is_installed(addon_signal: str) -> bool:
    """Return True if the addon that provides `addon_signal` is present.

    `addon_signal` is an operator id (e.g. "view3d.modal_operator_raycast")
    that the required addon registers. We check the operator actually exists
    in this Blender session via get_rna_type(), which raises if it's not
    registered. This is how addon-gated presets (requires_addon) decide
    whether to show.
    """
    import bpy
    try:
        mod_name, op_name = addon_signal.split(".", 1)
        op = getattr(getattr(bpy.ops, mod_name), op_name)
        op.get_rna_type()   # raises if the operator is not registered
        return True
    except Exception:
        return False


def get_category(cat_id: str) -> dict | None:
    for c in PRESET_CATEGORIES:
        if c["id"] == cat_id:
            return c
    return None


def get_category_label(cat_id: str) -> str:
    c = get_category(cat_id)
    return c["label"] if c else cat_id


def is_category_mutually_exclusive(cat_id: str) -> bool:
    c = get_category(cat_id)
    return bool(c and c.get("mutually_exclusive", False))


