def get_preset_by_id(preset_id: str) -> dict | None:
    for p in PRESETS:
        if p["id"] == preset_id:
            return p
    return None


def get_presets_by_category() -> dict[str, list[dict]]:
    """Return {category_id: [preset, ...]} preserving PRESET_CATEGORIES order
    so navigation appears first, then tools, etc. Any preset with an
    unknown category falls under its own key at the end."""
    result = {}
    for cat in PRESET_CATEGORIES:
        result[cat["id"]] = []
    for p in PRESETS:
        cat_id = p.get("category", "other")
        result.setdefault(cat_id, []).append(p)
    return result


def find_applied_preset_in_category(entries: list[dict], category_id: str) -> str:
    """Search the given entries list for any whose source_preset_category matches
    the requested category. Returns the source_preset_id of the first match, or
    "" if no matching entry exists.
    """
    for e in entries:
        if e.get("source_preset_category", "") == category_id:
            sid = e.get("source_preset_id", "")
            if sid:
                return sid
    return ""


def find_entries_from_preset(entries: list[dict], preset_id: str) -> list[dict]:
    """Return the subset of entries that were created by the given preset_id."""
    return [e for e in entries if e.get("source_preset_id", "") == preset_id]


# Fields that make up a preset entry's user-editable state. Used to detect
# whether an applied entry has been changed from its preset definition, and
# to restore it.
PRESET_STATE_FIELDS = (
    "custom_label",
    "custom_icon",
    "operator_ids",
    "key",
    "shift",
    "ctrl",
    "alt",
    "oskey",
    "key_modifier",
    "event_type",
    "repeat",
    "any",
    "extra_keybinds",
)


def find_preset_template(entry: dict) -> dict | None:
    """Find the original preset-entry template this entry came from. Matches on
    operator_ids first (stable across label/icon edits), then custom_label."""
    preset_id = entry.get("source_preset_id", "")
    if not preset_id:
        return None
    preset = get_preset_by_id(preset_id)
    if not preset:
        return None
    key = entry.get("source_preset_key", "")
    if key:
        for tpl in preset.get("entries", []):
            if tpl.get("custom_label", "") == key:
                return tpl
    ops = entry.get("operator_ids", "")
    for tpl in preset.get("entries", []):
        if tpl.get("operator_ids", "") == ops:
            return tpl
    label = entry.get("custom_label", "")
    for tpl in preset.get("entries", []):
        if tpl.get("custom_label", "") == label:
            return tpl
    return None


def preset_entry_differs(entry: dict, template: dict) -> bool:
    """True if the entry's state differs from its preset template."""
    for f in PRESET_STATE_FIELDS:
        if entry.get(f, "") != template.get(f, ""):
            return True
    return False
